   "titolo": "Carrefour Tunisia e i Villaggi SOS lanciano una raccolta fondi in oltre 100 negozi",
   "orig": "كارفور تونس وقرى الأطفال «س و س» يطلقان حملة تبرعات بأكثر من 100 مغازة",
