   "orig": "Live: Jillaroos begins World Cup defence with 40-0 win over Samoa",
   "lead": "Le Jillaroos, nazionale australiana di rugby league femminile campionessa in carica, hanno iniziato la difesa del titolo al Mondiale con una vittoria per 40-0 contro Samoa a Sydney. Jocelyn Kelleher è stata nominata migliore in campo al suo debutto. Nella stessa competizione, la squadra maschile Toa Samoa ha invece travolto la Francia nella partita d'apertura del torneo, con Sua Fa'alogo autore di quattro mete.",
