   "id": "z11884ee7",
   "sez": "italia",
   "titolo": "Schifani agli Stati Generali: 'I giovani devono poter scegliere di restare in Sicilia'",
   "orig": "Schifani agli Stati Generali: “I giovani devono poter scegliere di restare”. Scuola, lavoro e formazione al centro del progetto Sicilia",
   "lead": "Il presidente della Regione Siciliana Renato Schifani, intervenendo agli Stati Generali, ha dichiarato che i giovani devono poter scegliere di restare nella propria regione. Ha presentato un quadro degli stanziamenti regionali destinati a scuola, università e formazione professionale, collegandoli all'obiettivo di consentire a ragazze e ragazzi di studiare, acquisire competenze, lavorare e costruire un progetto di vita senza essere costretti a lasciare l'Isola per mancanza di opportunità.",
   "more": [
    "Gli \"Stati Generali\" sono incontri istituzionali periodici organizzati dalla Regione Siciliana per discutere strategie di sviluppo economico e sociale del territorio, spesso con la partecipazione di rappresentanti politici, imprenditoriali e del mondo dell'istruzione."
   ],
