   "titolo": "La Bulgaria chiede alla Nato sistemi anti-drone dopo gli attacchi nel Mar Nero",
   "orig": "Bulgaria seeks NATO anti-drone systems, says defence minister",
   "lead": "Il ministro della Difesa bulgaro Dimitar Stoyanov ha annunciato venerdì che la Bulgaria ha chiesto formalmente alla Nato di inviare aerei da combattimento e sistemi anti-drone per rafforzare le proprie defense, dopo una serie di attacchi con drone contro navi commerciali nel Mar Nero. Secondo HotNews, diverse navi mercantili sono state colpite nell'ultima settimana al largo delle coste di Romania e Bulgaria, e sia Bucarest che Sofia attribuiscono la responsabilità alla Russia.",
   "more": [
    "Il Mar Nero è diventato teatro di tensioni crescenti dall'inizio della guerra in Ucraina, con attacchi che minacciano le rotte commerciali marittime di Romania e Bulgaria, entrambi Paesi membri della Nato e dell'Unione europea."
   ],
