   "lead": "Secondo N1 Bosnia, Google collegherebbe il numero di telefono degli utenti Android a più account, senza che gli utenti ne siano consapevoli, modificando una delle impostazioni chiave della privacy. La testata spiega come sia possibile impedire questa associazione automatica. Lo riferisce N1 Bosnia.",
