   "titolo": "Kagame invita l'Africa a collaborare per il Gran Premio di Formula 1 in Ruanda",
   "orig": "Rwanda: Kagame Calls for African Collaboration On F1 Grand Prix",
   "lead": "Il presidente ruandese Paul Kagame ha chiesto ai Paesi africani di collaborare per garantire il successo del Gran Premio di Formula 1 africano che si disputerà in Ruanda, dopo aver ricevuto messaggi di sostegno dal presidente sudafricano Cyril Ramaphosa e da quello zambiano Hakainde Hichilema. L'appello punta a rendere l'evento un motivo di orgoglio per l'intero continente africano.",
   "more": [
    "La Formula 1 è il massimo campionato mondiale di automobilismo su pista; un eventuale Gran Premio africano rappresenterebbe un ritorno della categoria nel continente dopo decenni di assenza, con potenziali ricadute economiche e di visibilità per i Paesi coinvolti."
   ],
