   "titolo": "Compensi accessori docenti e ATA: fondi assegnati ma non ancora accreditati alle scuole",
   "orig": "Compensi accessori docenti e ATA, fondi assegnati ma non accreditati alle scuole. UIL Scuola al Ministero: “Sbloccare subito i pagamenti”",
   "lead": "La UIL Scuola ha inviato una lettera al Ministero dell'Istruzione e del Merito per segnalare che le risorse integrative destinate ai compensi accessori di docenti e personale ATA, assegnate con le note ministeriali del 18 novembre e del 5 dicembre 2025, non sono state ancora accreditate alle scuole. Il sindacato chiede di sbloccare immediatamente i pagamenti, denunciando il ritardo nell'erogazione dei fondi già stanziati. Lo riferisce Orizzonte Scuola.",
   "more": [
    "I compensi accessori sono somme aggiuntive allo stipendio base destinate a docenti e personale ATA per attività extra previste dai contratti scolastici; il loro ritardato accredito incide direttamente sulle retribuzioni del personale scolastico italiano."
   ],
