   "id": "z04792623",
   "sez": "economia",
   "titolo": "L'Iran continua a esportare GPL e carburante per aerei nonostante il blocco navale USA",
   "orig": "Iran ships some LPG, jet fuel despite US blockade, data shows",
   "lead": "Nonostante il blocco navale imposto dagli Stati Uniti, l'Iran è riuscito a esportare quantità di gas di petrolio liquefatto (GPL) e carburante per aerei a partire da luglio, secondo dati di intelligence marittima e fonti coinvolte nella sicurezza. Teheran avrebbe nascosto questi carichi tra un numero crescente di trasferimenti ship-to-ship, aggirando così le restrizioni imposte dalla marina statunitense nella regione.",
   "more": [
    "Il blocco navale statunitense contro l'Iran mira a limitare le esportazioni energetiche del Paese come parte delle sanzioni internazionali legate al programma nucleare iraniano; i trasferimenti ship-to-ship sono un metodo comune per eludere i controlli, trasbordando merci in mare aperto tra navi diverse."
   ],
