   "id": "z284d45bf",
   "sez": "musica",
   "titolo": "I Justice firmano la colonna sonora di GTA 6 con un brano insieme a Tame Impala, SZA e King Gizzard",
   "orig": "I Justice firmano la colonna sonora di “GTA 6” e pubblicano un brano con Tame Impala, SZA e King Gizzard & The Lizard Wizard: ascolta “Flower In A Hurricane”",
   "lead": "Il duo musicale Justice ha curato la colonna sonora di 'Grand Theft Auto VI' e ha pubblicato un nuovo singolo, 'Flower In A Hurricane', realizzato insieme a Tame Impala, SZA e King Gizzard & The Lizard Wizard. Il brano anticipa l'album 'Grand Theft Auto VI: The Album', la cui uscita è prevista per il 19 novembre, in contemporanea con il lancio del videogioco sviluppato da Rockstar Games. Lo riferisce OndaRock.",
