 "confronti": {
  "z1838bc4e": {
   "voci": [
    {
     "n": "Al Jazeera",
     "c": "Doha",
     "p": "QA",
     "t": "Riporta solo titolo e occhiello: Infantino avrebbe parlato alla riunione del board Fifa a Zurigo tra richieste di dimissioni. Giudizio parziale per assenza del testo completo.",
     "b": "t"
    },
    {
     "n": "The Guardian",
     "c": "Londra",
     "p": "UK",
     "t": "Si concentra sul premio per la pace Fifa assegnato a Trump, riportando che membri del consiglio hanno chiesto di abolirlo o 'depoliticizzarlo' dopo le polemiche. Cita un comitato interno che deciderà prima della riunione di Doha del 16 dicembre, e un membro anonimo del consiglio come fonte.",
     "b": "a"
    },
    {
     "n": "PBS NewsHour",
     "c": "Arlington",
     "p": "US",
     "t": "Racconta le scuse di Infantino per gli 'errori' nel piano di investimento da 4,2 miliardi di dollari con Kushner, poi abbandonato, e la delusione dei delegati europei che parlano di 'nessuna risposta satisfacente'. Cita Neuendorf e Debbie Hewitt come critici, e il membro africano Ahmed Yahya come sostenitore di Infantino.",
     "b": "a"
    },
    {
     "n": "Hespress English",
     "c": "Rabat",
     "p": "XX",
     "t": "Riporta le stesse dichiarazioni di Neuendorf ('nessuna risposta satisfacente') e Hewitt sulle scuse 'con contrizione', incentrandosi sul fallito progetto FFE e sul nuovo fondo di sviluppo da 6,35 miliardi di dollari. Menziona anche il caso Balogun e il premio per la pace a Trump come fattori di tensione.",
     "b": "a"
    },
    {
     "n": "Actu Cameroun",
     "c": "Yaoundé",
     "p": "XX",
     "t": "Riporta le scuse ufficiali di Infantino per gli 'errori di gestione e comunicazione' sul progetto FFE, citando le sue parole secondo cui si trattava solo di una 'proposta' e non di una 'decisione definitiva'. Dà rilievo al bilancio di Infantino e all'aumento dei fondi a 25 milioni di dollari per associazione membro.",
     "b": "a"
    }
   ],
   "divergono": "Il Guardian pone al centro la vicenda del premio per la pace a Trump e le pressioni per abolirlo, aspetto assente in Actu Cameroun che si concentra invece sul bilancio positivo di Infantino. PBS NewsHour e Hespress English condividono le stesse citazioni critiche di Neuendorf e Hewitt sull'assenza di risposte, mentre Actu Cameroun riporta solo le parole di scuse di Infantino senza le reazioni critiche europee. Le cifre differiscono: PBS parla di piano da 4,2 miliardi di dollari e fondo di sviluppo, Hespress cita 6,35 miliardi per il fondo sviluppo e 25 milioni per federazione, dato ripreso anche da Actu Cameroun."
  },
  "z5e80f2fb": {
   "voci": [
    {
     "n": "la Repubblica",
     "c": "Roma",
     "p": "IT",
     "t": "Riporta i tassi comunicati dal Tesoro per i due titoli, con cedole crescenti fino al 4,70% per il Btp Valore e il 22,25% come cedola unica finale per il Btp Valore Insieme. Testo essenzialmente informativo, senza commenti aggiuntivi.",
     "b": "a"
    },
    {
     "n": "ANSA",
     "c": "Roma",
     "p": "IT",
     "t": "Riferisce gli stessi tassi minimi garantiti comunicati dal Mef, aggiungendo dettagli pratici sul collocamento (dal 19 al 23 ottobre, riservato ai risparmiatori retail) e sulle modalità di sottoscrizione tramite home banking, banca o ufficio postale.",
     "b": "a"
    },
    {
     "n": "Il Messaggero",
     "c": "Roma",
     "p": "IT",
     "t": "Oltre ai tassi, contestualizza l'emissione come terza del 2026 dedicata ai piccoli risparmiatori e la collega all'aumento dei tassi Bce dovuto all'inflazione da «conflitto in Iran» e blocco dello stretto di Hormuz. Cita la cifra di oltre 121 miliardi raccolti dalle precedenti emissioni Btp Valore e Btp Italia.",
     "b": "a"
    },
    {
     "n": "la Repubblica – Economia",
     "c": "Roma",
     "p": "IT",
     "t": "Testo non leggibile: titolo e occhiello confermano gli stessi tassi (3,7%, 4,1%, 4,7% trimestrali) già riportati da Repubblica. Giudizio parziale per assenza del testo completo.",
     "b": "t"
    }
   ],
   "divergono": "Il Messaggero è il solo a inserire l'emissione in un contesto macroeconomico più ampio, collegandola all'aumento dei tassi Bce e alla crisi in Medio Oriente, e a citare la cifra complessiva di 121 miliardi raccolti dalle precedenti emissioni. ANSA si concentra maggiormente sugli aspetti operativi del collocamento (date, modalità di sottoscrizione), dettaglio meno presente in Repubblica, che offre invece una sintesi più scarna dei soli tassi."
  },
  "z53fc0e6f": {
   "voci": [
    {
     "n": "BBC News",
     "c": "Londra",
     "p": "UK",
     "t": "Ricostruzione ampia e cronologica: cita il vertice UE, le dichiarazioni di von der Leyen e Costa, gli attacchi russi a Kharkiv e Volyn (270.000 utenze senza corrente) e i droni ucraini su Mosca. Riporta Trump che definisce Zelensky 'più difficile di Putin' e gli scambi 'una vergogna'.",
     "b": "a"
    },
    {
     "n": "RTÉ News",
     "c": "Dublino",
     "p": "XX",
     "t": "Si concentra sul contrasto Trump-Zelensky, citando la frase 'non sono un grande fan di Zelensky' e il taglio dell'intelligence satellitare. Riporta oltre 100 civili uccisi in una settimana e la presenza del Taoiseach Micheál Martin al summit UE.",
     "b": "a"
    },
    {
     "n": "Meduza",
     "c": "Riga (in esilio)",
     "p": "XX",
     "t": "Riporta in modo diretto le dichiarazioni di Trump, incluso l'invito a elezioni in Ucraina e il dubbio sul sostegno popolare a Zelensky. Cita le reazioni ucraine e russe sulla presunta tregua energetica, definita 'una notizia' per Zelensky.",
     "b": "a"
    },
    {
     "n": "Moscow Times",
     "c": "Amsterdam (in esilio)",
     "p": "XX",
     "t": "Nel primo pezzo riporta la voce della Russia tramite Peskov, che dice di concordare 'pienamente' con Trump su Zelensky, e cita le richieste territoriali di Putin su Donetsk. Nel secondo pezzo si concentra sui dati militari: 644 droni ucraini intercettati, 94 su Mosca, voli cancellati e dichiarazione di Putin su danni 'non particolarmente significativi'.",
     "b": "a"
    },
    {
     "n": "The Guardian",
     "c": "Londra",
     "p": "UK",
     "t": "Dà ampio spazio alle reazioni europee, citando Macron, Tusk e von der Leyen che promette un 22° pacchetto di sanzioni. Riporta anche la vicenda Starlink e le rassicurazioni del ministro Streeting, oltre alle parole di Trump su Zelensky 'più difficile di Putin'.",
     "b": "a"
    }
   ],
   "divergono": "Le testate divergono nei dettagli numerici degli attacchi russi: BBC parla di 270.000 utenze senza corrente in Volyn, Moscow Times di 370.000. Il Moscow Times dà ampio risalto alla posizione del Cremlino (Peskov, Putin) come fonte diretta, mentre BBC, RTÉ e Guardian si concentrano sul fronte europeo e sulle reazioni di leader UE nominati esplicitamente (von der Leyen, Costa, Macron, Tusk). The Guardian è l'unica a dettagliare il nuovo pacchetto sanzionatorio UE e il caso Starlink con la conferma di Streeting. Meduza approfondisce più delle altre la richiesta di Trump di elezioni in Ucraina."
  }
 },
